public void Insert(Node node) {
    int index = 0;
    if(!isFull()) {
        //从新的空位置开始向上上滤，为node找到合适的位置
        for(index = length + 1; index != 1 && node.getPriority() > elements[index / 2].getPriority(); index /= 2) {
            elements[index] = elements[index / 2];
        }
        elements[index] = node;
        length ++;
    }
}

public Node deleteMax() {
    int parent = 1;
    if(!isEmpty()) {
        Node maxNode = elements[1];
        Node tempNode = elements[length --];
        //把最后一个元素下滤到合适的位置
        for(int child = 2; child <= length; child *= 2) {
            if(child < length && elements[child].getPriority() < elements[child + 1].getPriority()) {
                child ++;
            }
            if(tempNode.getPriority() >= elements[child].getPriority()) {
                break;
            }
            elements[parent] = elements[child];
            parent = child;
        }
        elements[parent] = tempNode;
        return maxNode;
    }
    return null;
}
